public class BankAccount {
    private static final double MIN_BALANCE = 500.0;
    private double  balance;
    private boolean frozen;
    public BankAccount(double initialDeposit) {
        if (initialDeposit < MIN_BALANCE)
            throw new IllegalArgumentException("Initial deposit must be at least ₹" + MIN_BALANCE);
        this.balance = initialDeposit;
        this.frozen  = false;
    }
    public boolean deposit(double amount) {
        if (frozen || amount <= 0) return false;
        balance += amount; return true;
    }
    public boolean withdraw(double amount) {
        if (frozen || amount <= 0) return false;
        if (balance - amount < MIN_BALANCE) return false;
        balance -= amount; return true;
    }
    public void freeze()   { this.frozen = true; }
    public void unfreeze() { this.frozen = false; }
    public double getBalance()  { return balance; }
    public boolean isFrozen()   { return frozen; }
}
// The object now protects its own invariants — no service can bypass withdrawal rules.

