public final class Temperature {
    private final double celsius; // single internal representation
    private static final double ABSOLUTE_ZERO_C = -273.15;
    private Temperature(double celsius) {
        if (celsius < ABSOLUTE_ZERO_C)
            throw new IllegalArgumentException("Below absolute zero: " + celsius + "°C");
        this.celsius = celsius;
    }
    // Static factory methods — named constructors
    public static Temperature ofCelsius(double c)    { return new Temperature(c); }
    public static Temperature ofFahrenheit(double f) { return new Temperature((f - 32) * 5.0 / 9.0); }
    public static Temperature ofKelvin(double k)     { return new Temperature(k - 273.15); }
    // Getters — computed from single source of truth
    public double toCelsius()    { return celsius; }
    public double toFahrenheit() { return celsius * 9.0 / 5.0 + 32; }
    public double toKelvin()     { return celsius + 273.15; }
    @Override public String toString() {
        return String.format("%.2f°C / %.2f°F / %.2fK", celsius, toFahrenheit(), toKelvin());
    }
}
